macro.command:
const version = "13.0.64";
try {
  // === DAE on/off — maintain enchantment on Unarmed Strike ===
  if (args[0] === "on" || args[0] === "off") {
    const lastArg = args[args.length - 1];
    const sourceActor = lastArg?.actorUuid ? await fromUuid(lastArg.actorUuid) : null;
    if (!sourceActor) return;
    const unarmed = sourceActor.items.find(i =>
      i.system?.identifier === "unarmed-strike" || i.name === "Unarmed Strike"
    );
    if (!unarmed) {
      if (args[0] === "on") ui.notifications?.warn("Elemental Attunement: no Unarmed Strike on actor.");
      return;
    }
    const existing = unarmed.effects.filter(e =>
      e.name === "Elemental Attunement" && e.type === "enchantment"
    );
    if (existing.length) await unarmed.deleteEmbeddedDocuments("ActiveEffect", existing.map(e => e.id));
    if (args[0] === "off") return;
    const enchantData = {
      name: "Elemental Attunement",
      img: lastArg.efData?.img ?? macroItem?.img ?? "icons/magic/fire/flame-burning-fist-strike.webp",
      type: "enchantment",
      origin: lastArg.origin ?? macroItem?.uuid,
      changes: [
        { key: "system.range.reach", value: "+10", mode: CONST.ACTIVE_EFFECT_MODES.ADD, priority: 20 }
      ]
    };
    await unarmed.createEmbeddedDocuments("ActiveEffect", [enchantData]);
    return;
  }

  // === midi-qol OnUse passes (fire only for Unarmed Strike workflows) ===
  if (args[0]?.tag !== "OnUse") return;
  if (!workflow || !workflow.item) return;
  if (workflow.item.system?.identifier !== "unarmed-strike" && workflow.item.name !== "Unarmed Strike") return;
  if (!workflow.hitTargets?.size) return;

  // ---- postDamageRoll: prompt for damage type, then push/pull (single pass) ----
  if (args[0].macroPass !== "postDamageRoll") return;
  if (workflow.elementalAttunementHandled) return;
  workflow.elementalAttunementHandled = true;

  // 1. Damage-type prompt
  const dmgChoice = await foundry.applications.api.DialogV2.wait({
    window: { title: "Elemental Attunement: Damage Type" },
    content: "<p>Choose damage type for this Unarmed Strike:</p>",
    buttons: [
      { action: "acid", label: "Acid", icon: "fa-solid fa-droplet" },
      { action: "cold", label: "Cold", icon: "fa-solid fa-snowflake" },
      { action: "fire", label: "Fire", icon: "fa-solid fa-fire" },
      { action: "lightning", label: "Lightning", icon: "fa-solid fa-bolt" },
      { action: "thunder", label: "Thunder", icon: "fa-solid fa-cloud-bolt" },
      { action: "none", label: "No Change", icon: "fa-solid fa-xmark" }
    ],
    close: () => "none"
  });
  if (dmgChoice && dmgChoice !== "none") {
    for (let i = 0; i < (workflow.damageRolls?.length ?? 0); i++) {
      const roll = workflow.damageRolls[i];
      if (roll?.options) roll.options.type = dmgChoice;
    }
    if (workflow.setDamageRolls) await workflow.setDamageRolls(workflow.damageRolls);
  } else {
    return;
  }

  // 2. Push/pull prompt + save + move
  const casterToken = workflow.token;
  if (!casterToken) return;
  const target = workflow.hitTargets.first();
  if (!target?.actor) return;
  const dist = MidiQOL.getDistance(casterToken, target, { wallsBlock: false });
  if (typeof dist !== "number" || dist < 0) return;

  const buttons = [
    { action: "10", label: "Push 10 ft Away", icon: "fa-solid fa-arrow-right" },
    { action: "5", label: "Push 5 ft Away", icon: "fa-solid fa-arrow-right" },
    { action: "0", label: "No Movement", icon: "fa-solid fa-xmark" }
  ];
  if (dist > 5) buttons.push({ action: "-5", label: "Pull 5 ft Toward", icon: "fa-solid fa-arrow-left" });
  if (dist > 10) buttons.push({ action: "-10", label: "Pull 10 ft Toward", icon: "fa-solid fa-arrow-left" });

  const moveChoice = await foundry.applications.api.DialogV2.wait({
    window: { title: "Elemental Attunement: Push/Pull" },
    content: `<p>Current distance: <strong>${dist} ft</strong>. Move the target?</p>`,
    buttons,
    close: () => "0"
  });
  const dx = Number(moveChoice);
  if (!dx) return;

  // Find the Elemental Push activity on the source feat.
  const pushActivity = macroItem.system.activities.find(a =>
    a.id === "elementalPushA00" || a.identifier === "elemental-push" || a.name === "Elemental Push"
  );
  if (!pushActivity) {
    console.error("Elemental Attunement: Elemental Push activity not found on source item.");
    return;
  }

  const saveWorkflow = await MidiQOL.completeActivityUse(
    pushActivity,
    { consumeUsage: false, consume: { resources: false, spellSlot: false } },
    {
      configureDialog: false,
      targetUuids: [target.document.uuid],
      workflowOptions: { autoRollDamage: "none", autoFastDamage: true, autoRollAttack: true }
    }
  );
  if (!saveWorkflow?.failedSaves?.size) return;

  // dx > 0 pushes away from caster; dx < 0 pulls toward caster.
  await MidiQOL.moveTokenAwayFromPoint(target, dx, casterToken.center);
} catch (err) {
  console.error(`Elemental Attunement ${version}`, err);
}
